# Look at how humanize works in the arrow module
with open('arrow/arrow.py') as f:
    content = f.read()

# Find the humanize method
lines = content.split('\n')
start = None
for i, line in enumerate(lines):
    if 'def humanize' in line:
        start = i
        break

if start:
    for i in range(start, min(start+80, len(lines))):
        print(f"{i+1}: {lines[i]}")
